  // strongest, so the blue-shift reads as a colour change and not just a brighter white.
  col = mix(col, mix(u_cDop, u_cHot, 0.35) * 1.4, smoothstep(1.0, 1.45, D) * 0.75);
  col = mix(col, mix(u_cDopDeep, u_cDop, 0.3) * 1.25, smoothstep(1.5, 2.3, D) * 0.6);
